const Card: React.FC<{ title: string; Icon: React.FC; frame: number; delay: number; fps: number }> = ({ title, Icon, frame, delay, fps }) => {
  const entrance = spring({ frame: frame - delay, fps, config: { damping: 16, mass: 0.8, stiffness: 90 } });
  const opacity = interpolate(entrance, [0, 1], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const scale = interpolate(entrance, [0, 1], [0.85, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const translateY = interpolate(entrance, [0, 1], [30, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  return (
    <div style={{
      width: 220,
      height: 280,
      backgroundColor: '#ffffff',
      borderRadius: 24,
      boxShadow: '0 12px 36px rgba(0,0,0,0.06), 0 4px 12px rgba(0,0,0,0.03)',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'flex-start',
      opacity,
      transform: `scale(${scale}) translateY(${translateY}px)`,
      transition: 'none',
      willChange: 'transform, opacity'
    }}>
      <div style={{ width: 110, height: 110, marginTop: 45 }}>
        <Icon />
      </div>
      <div style={{
        marginTop: 36,
        fontSize: 22,
        fontWeight: 600,
        color: '#1f2937',
        letterSpacing: '-0.02em'
      }}>
        {title}
      </div>
    </div>
  );
};

const ArrowRow: React.FC<{ frame: number; delay: number; fps: number }> = ({ frame, delay, fps }) => {
  const entrance = spring({ frame: frame - delay, fps, config: { damping: 14 } });
  const opacity = interpolate(entrance, [0, 1], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const translateX = interpolate(entrance, [0, 1], [-15, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  return (
    <div style={{
      width: 80,
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      opacity,
      transform: `translateX(${translateX}px)`,
      transition: 'none'
    }}>
      <ArrowIcon />
    </div>
  );
};

const WorkflowRow: React.FC<{ frame: number; fps: number; forceComplete?: boolean }> = ({ frame, fps, forceComplete = false }) => {
  const baseDelay = 15;
  return (
    <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center' }}>
      {WorkflowData.map((item, index) => {
        const cardDelay = baseDelay + index * 12;
        const arrowDelay = cardDelay + 8;
        return (
          <React.Fragment key={item.title}>
            <Card
              title={item.title}
              Icon={item.Icon}
              frame={forceComplete ? 9999 : frame}
              delay={cardDelay}
              fps={fps}
            />
            {index < WorkflowData.length - 1 && (
              <ArrowRow
                frame={forceComplete ? 9999 : frame}
                delay={arrowDelay}
                fps={fps}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
};


